 {view==='metrics'&&report?.summary&&<><div className="toolbar"><p>{task?'当前任务，含历史重试和失败':'全部任务'}</p><button onClick={()=>show('metrics')}>刷新</button></div><div className="metrics"><Metric label="已知模型往返耗时" value={time(report.summary.known_inference_ms)}/><Metric label="教师操作时间（估算）" value={time(report.human_active_ms)}/><Metric label="调用 / 失败 / 中断" value={`${report.summary.attempt_count} / ${report.summary.failed_count} / ${report.summary.interrupted_count}`}/><Metric label="中位 / 95%分位耗时" value={`${time(report.summary.p50_ms)} / ${time(report.summary.p95_ms)}`}/></div><p className="hint">{report.human_time_method}。{report.quota_note}</p><div className="toolbar"><span>纸本处理计时（手动）：{time(report.paper_manual_ms)}</span>{task&&<button disabled={busy} onClick={()=>work(async()=>{await api('/manual-timer',{task_id:task,action:report.running_timers?.length?'stop':'start'});Report(await api('/metrics?task_id='+task))})}>{report.running_timers?.length?'停止纸本计时':'开始纸本计时'}</button>}</div><p className="hint">手动计时从点击开始至停止，不推算“节省了多少时间”。</p><h2>每轮处理</h2><table><thead><tr><th>轮次 / 提交时间（最新在前）</th><th>状态</th><th>提交至结束</th><th>已知调用耗时</th><th>输入/输出词元</th></tr></thead><tbody>{report.runs.map((r:R)=><tr key={r.id}><td>{r.id.slice(0,8)}<small className='table-time'>{new Date(r.submitted_at||r.created_at).toLocaleString()}</small></td><td><Badge value={r.state}/></td><td>{time(r.wall_ms)}</td><td>{time(r.known_inference_ms)}</td><td>{r.input_tokens??'未报告'} / {r.output_tokens??'未报告'}</td></tr>)}</tbody></table><h2>班级耗时</h2><table><thead><tr><th>班级</th><th>页面 / 已复核</th><th>调用数</th><th>已知调用耗时</th></tr></thead><tbody>{report.groups.map((g:R)=><tr key={g.group_id}><td>{g.name}</td><td>{g.page_count} / {g.reviewed_pages}</td><td>{g.attempt_count}</td><td>{time(g.known_inference_ms)}</td></tr>)}</tbody></table><h2>提示词迭代线索</h2><table><thead><tr><th>提示词版本 / 最近调用</th><th>调用数</th><th>教师修改页数</th><th>中位 / 95%分位耗时</th></tr></thead><tbody>{report.prompt_versions.map((p:R)=><tr key={p.prompt_version_id}><td>{p.prompt_version_id}<small className="table-time">{p.latest_at?new Date(p.latest_at).toLocaleString():'未报告'}</small></td><td>{p.attempt_count}</td><td>{p.teacher_corrected_page_count}</td><td>{time(p.p50_ms)} / {time(p.p95_ms)}</td></tr>)}</tbody></table><p className="hint">教师修正率仅作迭代线索，不等同于模型准确率；必须人工筛选评测真值。</p><h2>每次调用</h2><table><thead><tr><th>用途 / 页面 / 开始时间（最新在前）</th><th>状态</th><th>往返耗时</th><th>请求模型/强度</th><th>实际报告</th><th>用量</th></tr></thead><tbody>{report.attempts.map((a:R)=><tr key={a.id}><td>{displayText(a.purpose)}/{a.page_id?.slice(0,6)||'范本'}<small className='table-time'>{new Date(a.started_at||a.created_at).toLocaleString()}</small></td><td><Badge value={a.state}/></td><td>{time(a.elapsed_ms)}</td><td>{a.config.model}/{displayText(a.config.effort)}</td><td>{a.actual_model||'未报告'} / {displayText(a.actual_service_tier)}</td><td>{usageText(a.usage)}</td></tr>)}</tbody></table></>}
 {view==='logs'&&report?.events&&<><div className="toolbar"><input placeholder="筛选错误码、事件或组件" value={filter} onChange={e=>Filter(e.target.value)}/><div className="actions"><button onClick={()=>show('logs')}>刷新</button><button onClick={()=>work(async()=>{const r=await api('/logs/export',{task_id:task||null});N('诊断包已保存：'+r.path)})}>导出脱敏诊断包</button></div></div><p className="hint">不含图片、学生转录、答案正文或凭据。教师反馈属于迭代线索，需筛选后用于评测；不会自动改动提示词或重新调用模型。</p><h2>错误分析</h2>{report.diagnostics.filter((x:R)=>JSON.stringify(x).toLowerCase().includes(filter.toLowerCase())).map((x:R)=><details className="log" key={x.id}><summary><b>{x.error_code}</b> {x.message}<small>{new Date(x.time).toLocaleString()}</small></summary><pre>{JSON.stringify(x,null,2)}</pre></details>)}<h2>功能运行事件</h2>{report.events.filter((x:R)=>JSON.stringify(x).toLowerCase().includes(filter.toLowerCase())).map((x:R)=><details className="log" key={x.event_id}><summary>#{x.event_id} <b>{eventText(x.event_type)}</b><small>{new Date(x.created_at).toLocaleString()}</small></summary><p className="hint">诊断原始事件：{x.event_type}</p><pre>{x.payload}</pre></details>)}</>}
